function wbExpertCategory(expert){if(wbExpertCategories.includes(expert.category))return expert.category;if(/品牌|公关|舆情|审核|合规/.test(`${expert.name} ${expert.category} ${(expert.tags||[]).join(' ')}`))return '品牌公关';if(/内容|设计|编导|视频|直播|社媒|制片|游戏|新媒体/.test(`${expert.name} ${expert.category} ${(expert.tags||[]).join(' ')}`))return '内容创作';return '广告投放';}
function wbExpertView(expert){const settings=workspace.expertSettings[expert.id]||{};return {...expert,name:settings.name||expert.name,category:wbExpertCategory(expert),knowledgeIds:settings.knowledgeIds||expert.knowledgeIds||[],pinned:workspace.pinnedExpertIds.includes(expert.id)};}
function wbVisibleExpert(expert){return !workspace.hiddenExpertIds.includes(expert.id);}
function wbAllExperts(){return [...wbCoreExperts,...workspace.experts,...wbPresetExperts].filter(wbVisibleExpert).map(wbExpertView);}
function wbSidebarExperts(){return [...wbCoreExperts,...workspace.experts].filter(wbVisibleExpert).map(wbExpertView).sort((a,b)=>Number(b.pinned)-Number(a.pinned));}
