function wbDrawExpertDetail(id){const expert=wbFindExpert(id);if(!expert)return;const skills=(expert.extensions||[]).filter(item=>item.type==='skill'),catalogSkills=R.catalog?.skills||window.AssistantScenarios?.skills||[],configuredSkills=(expert.skillIds||[]).map(skillId=>catalogSkills.find(item=>item.id===skillId)).filter(Boolean),skillRows=(skills.length?skills:configuredSkills.length?configuredSkills:(expert.tags||[]).map((name,index)=>({name,description:['完成目标拆解、判断与执行建议。','结合上下文输出结构化方案与检查点。','在交付前核对内容、风险和后续动作。'][index%3]})));wbExpertDetailDialog.innerHTML=`<div class="wb-expert-detail-shell"><header><div class="wb-expert-detail-title"><span>${wbExpertAvatarMarkup(expert.avatar,expert.name.slice(0,1))}</span><div><h2>${E(expert.name)}</h2><p>${E(expert.category||'专属专家')}</p></div></div><button type="button" data-r-action="wb-close-expert-detail" aria-label="关闭">×</button></header><main><p class="wb-expert-detail-summary">${E(expert.description||'专属工作专家')}</p><div class="wb-expert-detail-tags">${(expert.tags||[]).map(tag=>`<span>${E(tag)}</span>`).join('')}</div><section><h3>内置技能 <small>${skillRows.length}</small></h3><div class="wb-expert-skill-list">${skillRows.map(skill=>`<article><i>✓</i><div><b>${E(skill.name)}</b><p>${E(skill.description||'围绕当前任务提供专业判断与执行支持。')}</p></div></article>`).join('')||'<p>暂无内置技能</p>'}</div></section><section class="wb-expert-instruction-detail"><h3>Agent 指令</h3><p>${E(wbExpertInstruction(expert))}</p></section></main><footer><button type="button" class="solid" data-r-action="wb-detail-start-chat" data-id="${E(expert.id)}">发起对话</button></footer></div>`;if(!wbExpertDetailDialog.open)wbExpertDetailDialog.showModal();}
function wbExpertPrompts(expert){const tags=expert.tags?.length?expert.tags:['目标拆解','方案设计','执行复盘'];return [`帮我用${tags[0]}的方法梳理这次任务，并给出执行步骤`,`围绕${tags[1]||tags[0]}分析现状、问题和优先级`,`结合${tags[2]||tags[0]}输出一份可以直接推进的方案`];}
function wbDrawExpertShare(id){const expert=wbFindExpert(id);if(!expert)return;const shareUrl=new URL(location.href);shareUrl.searchParams.set('sharedExpert',expert.id);shareUrl.hash='ad-agent';const prompts=wbExpertPrompts(expert);wbExpertShareDialog.innerHTML=`<div class="wb-expert-share-shell"><header><span>${wbExpertAvatarMarkup(expert.avatar,expert.name.slice(0,1))}</span><div><h2>${E(expert.name)}</h2><p>${E(expert.category||'专属专家')}　<em>专家</em></p></div><button data-r-action="wb-close-expert-share" aria-label="关闭">×</button></header><main><h3>能力介绍</h3><p>${E(expert.description||'围绕工作目标提供专业判断、方案与执行支持。')}</p><h3>擅长领域</h3><div class="wb-expert-share-tags">${(expert.tags||[]).map(tag=>`<span>${E(tag)}</span>`).join('')||'<span>专属工作专家</span>'}</div><h3>💡 专家帮你做</h3>${prompts.map(prompt=>`<div class="wb-expert-share-prompt">“${E(prompt)}”<span>◔</span></div>`).join('')}</main><footer><p>请确认提示词和技能中不包含敏感信息后再进行分享</p><button class="solid" data-r-action="wb-copy-expert-link" data-url="${E(shareUrl.href)}">🔗　复制链接</button></footer></div>`;wbExpertShareDialog.showModal();}
