function wbDrawExpertFolder(id){const expert=wbFindExpert(id);if(!expert)return;const files=[['folder','agents'],['folder','avatars'],['file','README.md'],['folder','skills']];wbExpertFolderDialog.innerHTML=`<div class="wb-expert-folder-window"><header><i class="red"></i><i class="yellow"></i><i class="green"></i><button data-r-action="wb-close-expert-folder">‹</button><button data-r-action="wb-close-expert-folder">›</button><h2>${E(wbExpertFolderName(expert))}</h2><button data-r-action="wb-close-expert-folder" aria-label="关闭">×</button></header><div class="wb-expert-folder-body"><aside><b>◷　最近使用</b><b>▱　共享</b><small>个人收藏</small><b>⌘　应用程序</b><b>▣　桌面</b><b>□　文稿</b><b>⇩　下载</b><small>位置</small><b>☁　iCloud 云盘</b><b>⌂　miao</b></aside><main>${files.map(([type,name])=>`<article><span class="${type}">${type==='folder'?'':'TXT'}</span><b>${name}</b></article>`).join('')}</main></div></div>`;wbExpertFolderDialog.showModal();}

