function wbExtensionByKey(key){const [type,id]=key.split(':');return {...(wbExtensionCatalog[type]||[]).find(item=>item.id===id),type,key};}
function wbRenderSelectedExtensions(){const host=$('#wb-expert-selected-extensions');if(!host)return;const rows=(WB.expertDraftExtensions||[]).map(wbExtensionByKey).filter(item=>item.name);host.innerHTML=rows.length?rows.map(item=>`<span><i>${E(item.avatar)}</i><b>${E(item.name)}</b><small>${E(item.type==='plugin'?'插件':item.type==='skill'?'技能':'MCP')}</small><button type="button" data-r-action="wb-remove-expert-extension" data-id="${E(item.key)}" aria-label="移除${E(item.name)}">×</button></span>`).join(''):'<p>尚未添加扩展能力</p>';}
function wbDrawExpertForm(editId=''){
 const source=editId?workspace.experts.find(item=>item.id===editId):null;
 wbExpertDialog.setAttribute('aria-label',source?'修改专家':'新建专家');
 WB.expertDraftExtensions=(source?.extensions||[]).map(item=>item.key||`${item.type}:${item.id}`);WB.expertDraftKnowledge=[...(source?.knowledgeIds||[])];WB.expertDraftAvatar=source?.avatar||'';
 wbExpertDialog.innerHTML=`<form id="wb-expert-form"><header><div><small>${source?'EDIT AN EXPERT':'CREATE AN EXPERT'}</small><h2>${source?'修改专家':'新建专家'}</h2><p>${source?'修改专家头像、名称、工作指令、知识和扩展能力。':'设置专家身份、工作指令、知识和可使用的扩展能力。'}</p></div><button type="button" data-r-action="wb-close-expert" aria-label="关闭">×</button></header><main><section class="wb-expert-avatar-picker"><b>Agent 头像</b><label class="wb-expert-avatar-upload" title="上传头像"><input id="wb-expert-avatar-file" type="file" accept="image/png,image/jpeg,image/webp"><span class="wb-expert-avatar-preview" id="wb-expert-avatar-preview">${source?.avatar?wbExpertAvatarMarkup(source.avatar,'AI'):'<strong>AI</strong>'}<em>${source?'更换头像':'上传头像'}</em></span><small>支持 JPG、PNG、WebP，图片会自动裁切为正方形</small></label></section><label class="wb-expert-field wb-expert-name"><b>Agent 名称</b><input name="name" maxlength="24" required placeholder="例如：自媒体运营达人" value="${E(source?.name||'')}"></label><label class="wb-expert-field wb-expert-instruction"><span><b>Agent 指令</b><small id="wb-expert-instruction-count">0 / 2000</small></span><p>写清楚身份、判断标准、输出格式和工作边界。指令会随专家进入每次对话。</p><textarea name="instruction" maxlength="2000" required placeholder="例如：你是一名资深自媒体运营专家。先核对平台、受众与传播目标，再给出选题、内容结构、发布节奏和复盘指标……">${E(source?.instruction||'')}</textarea></label><section class="wb-expert-knowledge-picker"><div><h3>添加知识</h3><p>关联专家可以优先使用的资料，可按一二级文件夹或单条知识选择。</p></div><button type="button" data-r-action="wb-open-expert-knowledge">＋ 选择知识</button><div id="wb-expert-selected-knowledge"></div></section><section class="wb-expert-capabilities"><div><h3>扩展能力</h3><p>为专家添加插件、技能和 MCP；实际调用仍需遵循对应服务的授权范围。</p></div><button type="button" data-r-action="wb-open-expert-extensions">＋ 添加扩展能力</button><div id="wb-expert-selected-extensions"></div></section></main><footer><button type="button" data-r-action="wb-close-expert">取消</button><button type="submit" class="solid">${source?'保存修改':'创建专家'}</button></footer></form>`;
 const form=$('#wb-expert-form'),instruction=form.elements.instruction,count=$('#wb-expert-instruction-count'),avatarInput=$('#wb-expert-avatar-file'),avatarPreview=$('#wb-expert-avatar-preview');instruction.oninput=()=>count.textContent=`${[...instruction.value].length} / 2000`;instruction.oninput();avatarInput.onchange=async()=>{const file=avatarInput.files?.[0];if(!file)return;try{WB.expertDraftAvatar=await wbReadExpertAvatar(file);avatarPreview.innerHTML=`<img src="${E(WB.expertDraftAvatar)}" alt="已选择的头像"><em>更换头像</em>`;}catch(error){avatarInput.value='';toast(error.message||'头像上传失败');}};wbRenderSelectedKnowledge();wbRenderSelectedExtensions();
 form.onsubmit=event=>{event.preventDefault();const data=new FormData(form),name=String(data.get('name')||'').trim(),instruction=String(data.get('instruction')||'').trim();if(!name||!instruction)return toast('请填写 Agent 名称和指令');const extensions=(WB.expertDraftExtensions||[]).map(wbExtensionByKey).filter(item=>item.name),skillIds=extensions.filter(item=>item.type==='skill').map(item=>item.id),category=skillIds.includes('public-opinion')?'品牌公关':skillIds.some(id=>['script-design','creative-review'].includes(id))?'内容创作':'广告投放',values={name,avatar:WB.expertDraftAvatar||source?.avatar||'AI',category,description:source?.description||'由你创建的专属专家',instruction,knowledgeIds:[...(WB.expertDraftKnowledge||[])],extensions:extensions.map(({key,type,id,name,avatar,description,meta})=>({key,type,id,name,avatar,description,meta})),skillIds,mcps:extensions.filter(item=>item.type==='mcp').map(item=>item.id),tags:extensions.slice(0,3).map(item=>item.name),uses:source?.uses||'新建',custom:true};wbExpertDialog.close();if(source){Object.assign(source,values,{updated:Date.now()});persist();WB.expertCategory='我的专家';renderAssistant();toast(`专家「${source.name}」已更新`);}else wbShowExpertCreating({id:uid(),...values,created:Date.now()});};
}
function wbDrawExtensionDialog(){const tab=WB.expertExtensionTab||'plugin',query=(WB.expertExtensionQuery||'').trim().toLowerCase(),rows=(wbExtensionCatalog[tab]||[]).filter(item=>(item.name+' '+item.description).toLowerCase().includes(query));wbExpertExtensionDialog.innerHTML=`<div class="wb-extension-shell"><aside><h2>扩展</h2>${[['plugin','插件'],['skill','技能'],['mcp','MCP']].map(([id,label])=>`<button class="${tab===id?'active':''}" data-r-action="wb-extension-tab" data-id="${id}">${label}</button>`).join('')}</aside><main><header><div><h2>添加${tab==='plugin'?'插件':tab==='skill'?'技能':' MCP'}</h2><p>选择后会加入当前专家的扩展能力。</p></div><label>${icon('search')}<input id="wb-extension-query" placeholder="搜索${tab==='plugin'?'插件':tab==='skill'?'技能':'MCP'}" value="${E(WB.expertExtensionQuery||'')}"></label><button data-r-action="wb-close-expert-extensions" aria-label="关闭">×</button></header><section>${rows.map(item=>{const key=`${tab}:${item.id}`,added=(WB.expertDraftExtensions||[]).includes(key);return `<article><span>${E(item.avatar)}</span><div><h3>${E(item.name)}</h3><p>${E(item.description)}</p><small>${E(item.meta)}</small></div><button data-r-action="wb-add-expert-extension" data-id="${E(key)}" ${added?'disabled':''}>${added?'已添加':'添加'}</button></article>`;}).join('')||'<div class="wb-extension-empty">没有找到匹配的扩展能力</div>'}</section></main></div>`;const search=$('#wb-extension-query');if(search)search.oninput=event=>{WB.expertExtensionQuery=event.target.value;const position=event.target.selectionStart;wbDrawExtensionDialog();$('#wb-extension-query').focus();$('#wb-extension-query').setSelectionRange(position,position);};}
