function wbShowExpertCreating(expert){wbExpertCreatingDialog.innerHTML=`<div class="wb-expert-creating"><span class="wb-creating-spinner"></span><h2>Agent（${E(expert.name)}）正在创建中</h2><p>正在准备专家配置，创建完成后会自动显示在专家列表中。</p><div><i></i>准备专家环境</div><button type="button" data-r-action="wb-close-expert-creating">返回消息列表</button></div>`;wbExpertCreatingDialog.showModal();clearTimeout(WB.expertCreatingTimer);WB.expertCreatingTimer=setTimeout(()=>{workspace.experts.unshift(expert);persist();if(wbExpertCreatingDialog.open)wbExpertCreatingDialog.close();WB.expertCategory='我的专家';WB.expertQuery='';renderAssistant();toast(`专家「${expert.name}」创建完成`);},1400);}
